class Solution {
  public int firstUniqueFreq(int[] nums) {
    int[] freq = new int[100001];
    for (int x : nums) freq[x]++;
    int[] freqCount = new int[nums.length + 1];
    for (int f : freq) if (f > 0) freqCount[f]++;
    for (int x : nums) {
      if (freqCount[freq[x]] == 1) return x;
    }
    return -1;
  }
}
